Deployment Orchestration với Bash Scripts Tổng quan Deployment orchestration tự động hóa quá trình triển khai nhiều CloudFormation stacks theo đúng thứ tự với xử lý lỗi và validation phù hợp.
Kiến trúc Deployment Scripts scripts/ ├── deploy.sh # Script orchestration chính ├── deploy-core.sh # Triển khai core stack ├── deploy-service.sh # Template triển khai service stack └── utils.sh # Shared utility functions Script Orchestration Chính deploy.sh - Điều phối toàn bộ deployment:
#!/bin/bash set -e # Thoát khi có lỗi set -o pipefail # Bắt lỗi trong pipes # Cấu hình ENVIRONMENT=${1:-staging} REGION=${2:-us-east-1} CORE_STACK_NAME=&#34;travel-guide-core-${ENVIRONMENT}&#34; echo &#34;🚀 Bắt đầu deployment tới ${ENVIRONMENT}&#34; # Bước 1: Setup deployment bucket echo &#34;📦 Thiết lập deployment bucket...&#34; ./scripts/setup-bucket.sh $ENVIRONMENT $REGION # Bước 2: Deploy Core Stack echo &#34;🏗️ Deploying Core Stack...&#34; ./scripts/deploy-core.sh $ENVIRONMENT $REGION # Đợi core stack hoàn thành echo &#34;⏳ Đợi Core Stack...&#34; aws cloudformation wait stack-create-complete \ --stack-name $CORE_STACK_NAME \ --region $REGION echo &#34;✅ Core Stack deployed thành công&#34; # Bước 3: Deploy Service Stacks SERVICES=(&#34;auth&#34; &#34;articles&#34; &#34;media&#34; &#34;ai&#34; &#34;gallery&#34; &#34;notification&#34;) for service in &#34;${SERVICES[@]}&#34;; do echo &#34;🔧 Deploying ${service} service...&#34; ./scripts/deploy-service.sh $service $ENVIRONMENT $REGION done echo &#34;✅ Tất cả services deployed thành công&#34; Xử lý Lỗi Xử lý lỗi toàn diện:
#!/bin/bash # Thoát khi có lỗi set -e # Thoát khi biến undefined set -u # Bắt lỗi trong pipes set -o pipefail # Cleanup function cleanup() { local exit_code=$? if [ $exit_code -ne 0 ]; then echo &#34;❌ Deployment thất bại với exit code: $exit_code&#34; echo &#34;📋 Kiểm tra CloudFormation events:&#34; echo &#34;aws cloudformation describe-stack-events --stack-name $STACK_NAME&#34; fi } # Đăng ký cleanup khi exit trap cleanup EXIT Chiến lược Rollback Automatic Rollback:
# CloudFormation tự động rollback khi thất bại aws cloudformation deploy \ --template-file template.yaml \ --stack-name my-stack \ --disable-rollback false # Hành vi mặc định Manual Rollback:
# Xóa failed stack aws cloudformation delete-stack --stack-name my-stack # Redeploy phiên bản trước git checkout v1.2.3 ./deploy.sh staging Các bước Validation Pre-deployment validation:
# 1. Validate template syntax aws cloudformation validate-template \ --template-body file://template.yaml # 2. Lint template cfn-lint template.yaml # 3. Kiểm tra parameter file jq empty &lt; parameters/staging.json # 4. Verify AWS credentials aws sts get-caller-identity Parallel Deployment Deploy services song song (nhanh hơn):
#!/bin/bash SERVICES=(&#34;auth&#34; &#34;articles&#34; &#34;media&#34; &#34;ai&#34; &#34;gallery&#34; &#34;notification&#34;) # Deploy tất cả services ở background for service in &#34;${SERVICES[@]}&#34;; do ./scripts/deploy-service.sh $service $ENVIRONMENT $REGION &amp; done # Đợi tất cả background jobs wait echo &#34;✅ Tất cả services deployed&#34; Điểm chính Orchestration scripts tự động hóa multi-stack deployment Error handling ngăn chặn partial deployments Validation bắt lỗi trước khi deployment Rollback strategies cho phép phục hồi nhanh Parallel deployment tăng tốc quá trình Logging giúp debug issues Best Practices Luôn validate templates trước deployment Dùng set -e để thoát khi có lỗi Implement retry logic cho transient failures Log tất cả operations để debugging Test scripts trong staging trước production Document deployment process trong README
